contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 identifier, uint256 time, bytes memory ancillaryData, bool fromAsserter) public payable {
        bool requestReverted;
        bool resolvedReverted;
        bool disputedReverted;

        c.getAssertionPolicy(identifier);
        c.isDisputeAllowed(identifier, address(this));
        c.getPrice(identifier, time, ancillaryData);

        if (fromAsserter) {
            requestReverted = false;
            c.requestPrice(identifier, time, ancillaryData);
        } else {
            try c.requestPrice(identifier, time, ancillaryData) {
                requestReverted = false;
            } catch {
                requestReverted = true;
            }
        }

        try c.assertionResolvedCallback(identifier, true) {
            resolvedReverted = false;
        } catch {
            resolvedReverted = true;
        }

        try c.assertionDisputedCallback(identifier) {
            disputedReverted = false;
        } catch {
            disputedReverted = true;
        }

        assert(
            fromAsserter
                ? (!requestReverted && resolvedReverted && disputedReverted)
                : (requestReverted && resolvedReverted && disputedReverted)
        );
    }

    receive() external payable {}
}

