contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 assertionId, bool assertedTruthfully, address caller) public {
        require(caller != address(this), "choose a caller other than the test contract");

        bool resolvedReverted;
        bool disputedReverted;

        if (caller == address(this)) {
            resolvedReverted = false;
            disputedReverted = false;
        } else {

            (bool s1, ) = address(c).call(
                abi.encodeWithSelector(
                    bytes4(keccak256("assertionResolvedCallback(bytes32,bool)")),
                    assertionId,
                    assertedTruthfully
                )
            );
            resolvedReverted = !s1;
        }

        if (caller == address(this)) {
            disputedReverted = false;
        } else {
            (bool s2, ) = address(c).call(
                abi.encodeWithSelector(bytes4(keccak256("assertionDisputedCallback(bytes32)")), assertionId)
            );
            disputedReverted = !s2;
        }

        assert(resolvedReverted && disputedReverted);
    }

    receive() external payable {}
}

