contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 assertionId, address disputeCaller) public payable {
        require(address(this) != address(c.optimisticAsserter()), "test contract must not be the optimistic asserter");

        bool policyReverted;
        try c.getAssertionPolicy(assertionId) returns (EscalationManagerInterface.AssertionPolicy memory policy) {
            policyReverted = false;
            assert(!policy.blockAssertion);
            assert(!policy.arbitrateViaEscalationManager);
            assert(!policy.discardOracle);
            assert(!policy.validateDisputers);
        } catch {
            policyReverted = true;
        }
        assert(!policyReverted);

        bool disputeAllowedReverted;
        bool disputeAllowed;
        try c.isDisputeAllowed(assertionId, disputeCaller) returns (bool allowed) {
            disputeAllowedReverted = false;
            disputeAllowed = allowed;
        } catch {
            disputeAllowedReverted = true;
        }
        assert(!disputeAllowedReverted);
        assert(disputeAllowed);

        bool requestPriceReverted;
        try c.requestPrice(bytes32(0), 0, "") {
            requestPriceReverted = false;
        } catch {
            requestPriceReverted = true;
        }
        assert(requestPriceReverted);

        bool resolvedCallbackReverted;
        try c.assertionResolvedCallback(assertionId, true) {
            resolvedCallbackReverted = false;
        } catch {
            resolvedCallbackReverted = true;
        }
        assert(resolvedCallbackReverted);

        bool disputedCallbackReverted;
        try c.assertionDisputedCallback(assertionId) {
            disputedCallbackReverted = false;
        } catch {
            disputedCallbackReverted = true;
        }
        assert(disputedCallbackReverted);

        assert(address(c).balance == 0);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 assertionId, address disputeCaller) public payable {
        require(address(this) != address(c.optimisticAsserter()), "test contract must not be the optimistic asserter");

        bool policyReverted;
        EscalationManagerInterface.AssertionPolicy memory policy;
        try c.getAssertionPolicy(assertionId) returns (EscalationManagerInterface.AssertionPolicy memory p) {
            policy = p;
            policyReverted = false;
        } catch {
            policyReverted = true;
        }

        bool disputeAllowedReverted;
        bool disputeAllowed;
        try c.isDisputeAllowed(assertionId, disputeCaller) returns (bool allowed) {
            disputeAllowed = allowed;
            disputeAllowedReverted = false;
        } catch {
            disputeAllowedReverted = true;
        }

        bool requestPriceReverted;
        try c.requestPrice(bytes32(0), 0, "") {
            requestPriceReverted = false;
        } catch {
            requestPriceReverted = true;
        }

        bool resolvedCallbackReverted;
        try c.assertionResolvedCallback(assertionId, true) {
            resolvedCallbackReverted = false;
        } catch {
            resolvedCallbackReverted = true;
        }

        bool disputedCallbackReverted;
        try c.assertionDisputedCallback(assertionId) {
            disputedCallbackReverted = false;
        } catch {
            disputedCallbackReverted = true;
        }

        assert(
            !policyReverted &&
            !policy.blockAssertion &&
            !policy.arbitrateViaEscalationManager &&
            !policy.discardOracle &&
            !policy.validateDisputers &&
            !disputeAllowedReverted &&
            disputeAllowed &&
            requestPriceReverted &&
            resolvedCallbackReverted &&
            disputedCallbackReverted
        );
    }

    receive() external payable {}
}

