contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, bytes32 assertionId, bool assertedTruthfully, bytes calldata ancillaryData, uint256 time) public payable {
        require(caller != address(this), "caller must not be this test contract");

        // Let c capture its own optimistic asserter address through a public getter.
        address optimisticAsserterAddr = address(c.optimisticAsserter());
        require(caller != optimisticAsserterAddr, "caller must not be the asserter");

        // The only public getter that proves our rule is about non-asserter callers.
        // (No direct state mutation is needed to test the access-control rule.)
        bool policyOk;
        try c.getAssertionPolicy(assertionId) returns (EscalationManagerInterface.AssertionPolicy memory) {
            policyOk = true;
        } catch {
            policyOk = false;
        }
        require(policyOk, "getAssertionPolicy must not revert");

        bool disputeAllowedOk;
        try c.isDisputeAllowed(assertionId, caller) returns (bool) {
            disputeAllowedOk = true;
        } catch {
            disputeAllowedOk = false;
        }
        require(disputeAllowedOk, "isDisputeAllowed must not revert");

        // From here on we simulate the actions an arbitrary caller would try.
        // Because the caller parameter is not the optimistic asserter, all these
        // state-changing calls must revert.
        bool requestPriceReverted;
        try c.requestPrice(bytes32(0), time, ancillaryData) {
            requestPriceReverted = false;
        } catch {
            requestPriceReverted = true;
        }

        bool resolvedCallbackReverted;
        try c.assertionResolvedCallback(assertionId, assertedTruthfully) {
            resolvedCallbackReverted = false;
        } catch {
            resolvedCallbackReverted = true;
        }

        bool disputedCallbackReverted;
        try c.assertionDisputedCallback(assertionId) {
            disputedCallbackReverted = false;
        } catch {
            disputedCallbackReverted = true;
        }

        // General rule: when the caller is not the optimistic asserter, every
        // onlyOptimisticAsserter-protected entry point must revert, while the two
        // unprotected view functions must succeed.
        assert(
            requestPriceReverted && resolvedCallbackReverted && disputedCallbackReverted && policyOk && disputeAllowedOk
        );
    }

    receive() external payable {}
}

