contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 assertionId, address disputeCaller) public {
        require(true);

        EscalationManagerInterface.AssertionPolicy memory policyBefore = c.getAssertionPolicy(assertionId);
        bool disputeAllowedBefore = c.isDisputeAllowed(assertionId, disputeCaller);

        require(policyBefore.blockAssertion == false);

        bool callReverted;
        try c.assertionResolvedCallback(assertionId, true) {
            callReverted = false;
        } catch {
            callReverted = true;
        }

        EscalationManagerInterface.AssertionPolicy memory policyAfter = c.getAssertionPolicy(assertionId);
        bool disputeAllowedAfter = c.isDisputeAllowed(assertionId, disputeCaller);

        assert(
            callReverted == true &&
            policyAfter.blockAssertion == policyBefore.blockAssertion &&
            policyAfter.arbitrateViaEscalationManager == policyBefore.arbitrateViaEscalationManager &&
            policyAfter.discardOracle == policyBefore.discardOracle &&
            policyAfter.validateDisputers == policyBefore.validateDisputers &&
            policyBefore.blockAssertion == false &&
            policyBefore.arbitrateViaEscalationManager == false &&
            policyBefore.discardOracle == false &&
            policyBefore.validateDisputers == false &&
            disputeAllowedAfter == disputeAllowedBefore &&
            disputeAllowedBefore == true
        );
    }

    receive() external payable {}
}

