contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 assertionId) public payable {
        (bool success, bytes memory data) = address(c).staticcall(
            abi.encodeWithSignature("getAssertionPolicy(bytes32)", assertionId)
        );
        bool ok = success && data.length >= 128;
        if (ok) {
            bool blockAssertion;
            bool arbitrateViaEscalationManager;
            bool discardOracle;
            bool validateDisputers;
            assembly {
                blockAssertion := mload(add(data, 32))
                arbitrateViaEscalationManager := mload(add(data, 64))
                discardOracle := mload(add(data, 96))
                validateDisputers := mload(add(data, 128))
            }
            ok = !blockAssertion && !arbitrateViaEscalationManager && !discardOracle && !validateDisputers;
        }
        assert(ok);
    }

    receive() external payable {}
}

