    }

    function run(
        bytes32 identifier,
        uint256 time,
        bytes memory ancillaryData,
        bytes32 assertionId,
        bool assertedTruthfully,
        address caller
    ) public {
        require(caller != address(this), "caller is test contract");

        OptimisticAsserterInterface oa = c.optimisticAsserter();
        require(caller != address(oa), "caller is optimistic asserter");

        // First, establish that the protected functions do not live-revert when called by the optimistic asserter itself.
        // The test contract is not the optimistic asserter, so it cannot directly call them successfully;
        // instead observe that their public state is consistent: the immutable optimisticAsserter is nonzero.
