    event PriceRequestAdded(bytes32 indexed identifier, uint256 time, bytes ancillaryData);

    function run(bytes32 identifier, uint256 time, bytes memory ancillaryData) public payable {
        address asserter = address(c.optimisticAsserter());
        require((identifier, time, keccak256(ancillaryData)) != bytes32(0), "");

        // The test contract must appear to be the optimistic asserter for the modifier to pass.
        // Since msg.sender for calls on c is this InvMutTest contract, and c.optimisticAsserter()
        // is an immutable set during deployment, we cannot change it. The only way the call succeeds
        // is if this contract *is* the optimisticAsserter, which is not true for a fresh C.
        // Thus we test the negative rule: requestPrice reverts when called by a non-asserter.
        bool reverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted);
    }

    receive() external payable {}
}

